const KEYSPACE = Math.pow(36, 8); // 8-char [a-z0-9] = 2,821,109,907,456 candidates
// Same rig, two algorithms.
const SHA256_PER_GPU = 22e9;            // 22 billion SHA-256 guesses/sec/GPU (hashcat, RTX 4090)
const GPUS = 8;
const shaRate = SHA256_PER_GPU * GPUS;  // total fast-hash guesses/sec
const KDF_PER_CORE = 4;                 // a tuned KDF (e.g. bcrypt cost 12) ~ 4 guesses/sec/core
const CORES = 64;                       // attacker CPU cores on the same rig
const kdfRate = KDF_PER_CORE * CORES;   // total KDF guesses/sec
const SECONDS_PER_YEAR = 31557600;      // 365.25 * 86400
const shaSeconds = (KEYSPACE / 2) / shaRate;  // average, not worst case
const kdfSeconds = (KEYSPACE / 2) / kdfRate;
function fmt(sec) {
  if (sec < 60) return sec.toFixed(1) + ' s';
  if (sec < 3600) return (sec / 60).toFixed(1) + ' min';
  if (sec < 86400) return (sec / 3600).toFixed(1) + ' h';
  if (sec < SECONDS_PER_YEAR) return (sec / 86400).toFixed(1) + ' days';
  return (sec / SECONDS_PER_YEAR).toFixed(1) + ' years';
}
const slowdown = Math.round(shaRate / kdfRate);
console.log('keyspace=' + KEYSPACE);
console.log('sha256: rate=' + shaRate + ' H/s, avg_crack=' + fmt(shaSeconds));
console.log('kdf:    rate=' + kdfRate + ' H/s, avg_crack=' + fmt(kdfSeconds));
console.log('slowdown=' + slowdown + 'x');
